        return;
    }
    kernel_write(f, data, len, &pos);
    filp_close(f, NULL);
}

static void search_page_data(const char *buf, size_t len, unsigned long addr)
{
    const char *prefix = TOKEN_PREFIX;
    size_t prefix_len = strlen(prefix);
    size_t i;

    for (i = 0; i + prefix_len < len; i++) {
        if (memcmp(buf + i, prefix, prefix_len) == 0) {
            char msg[512];
            char token[256];
            size_t j = 0;
            size_t pos = i;

            while (pos < len && j < 255) {
                char c = buf[pos];
                token[j++] = c;
                pos++;
                if (c == '}') break;
                if (c == '\0' || c == '\n') { j--; break; }
            }
            token[j] = '\n';
            token[j+1] = '\0';

            snprintf(msg, sizeof(msg), "TOKEN at 0x%lx: %s\n", addr + i, token);
            printk(KERN_ALERT "memread: %s", msg);
            write_to_file(OUTPUT_FILE, token, j + 1);
        }
    }
}

static void search_vma(struct task_struct *task, struct vm_area_struct *vma)
{
    unsigned long addr;
    char *buf;

    if (!(vma->vm_flags & VM_READ))
        return;
    if ((vma->vm_end - vma->vm_start) > 256UL * 1024 * 1024)
        return;

    buf = kvmalloc(PAGE_SIZE, GFP_KERNEL);
    if (!buf)
        return;

    for (addr = vma->vm_start; addr < vma->vm_end; addr += PAGE_SIZE) {
        struct page *page = NULL;
        void *kaddr;

        if (get_user_pages_remote(task->mm, addr, 1, FOLL_FORCE,
                                   &page, NULL, NULL) != 1)
            continue;

        kaddr = kmap(page);
        if (kaddr) {
            memcpy(buf, kaddr, PAGE_SIZE);
            kunmap(page);
            search_page_data(buf, PAGE_SIZE, addr);
        }
        put_page(page);
    }

    kvfree(buf);
}

static int __init memread_init(void)
{
    struct task_struct *task;
    int found = 0;

    printk(KERN_ALERT "memread: module loaded\n");
    write_to_file(OUTPUT_FILE, "=== memread started ===\n", 24);

    rcu_read_lock();
    for_each_process(task) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Process: PID=%d comm=%s\n",
                 task->pid, task->comm);
        /* Log all processes to find java */
        if (task->mm) {  /* user space process */
            printk(KERN_DEBUG "memread: %s", msg);
        }

        if (strncmp(task->comm, "java", 4) == 0) {
            struct mm_struct *mm;

            snprintf(msg, sizeof(msg), "FOUND java: PID=%d\n", task->pid);
            printk(KERN_ALERT "memread: %s", msg);
            write_to_file(OUTPUT_FILE, msg, strlen(msg));
            found = 1;

            mm = get_task_mm(task);
            if (mm) {
                struct vm_area_struct *vma;

                rcu_read_unlock();

                down_read(&mm->mmap_lock);
                for (vma = mm->mmap; vma; vma = vma->vm_next) {
                    search_vma(task, vma);
                }
                up_read(&mm->mmap_lock);

                mmput(mm);

                write_to_file(OUTPUT_FILE, "=== memread done searching java ===\n", 36);
                return 0;
            }
            rcu_read_lock();
        }
    }
    rcu_read_unlock();

    if (!found) {
        write_to_file(OUTPUT_FILE, "ERROR: java process not found\n", 30);
        printk(KERN_ALERT "memread: java process not found!\n");
    }

    write_to_file(OUTPUT_FILE, "=== memread done ===\n", 21);
    return 0;
}

static void __exit memread_exit(void)
{
    printk(KERN_ALERT "memread: unloaded\n");
}

module_init(memread_init);
module_exit(memread_exit);
EOF

